  7	public final class Graph implements Iterable<Integer> {
  8	    private final List<List<Integer>> adjacencyList;
  9	
 10	    private Graph(List<List<Integer>> adjacencyList) {
 11	        this.adjacencyList = adjacencyList;
 12	    }
 13	
 14	    public static Graph fromEdgePairs(int vertexCount, int[][] edgePairs) {
 15	        requireEdgePairs(edgePairs);
 16	
 17	        List<Edge> edges = new ArrayList<>(edgePairs.length);
 18	        for (int edgeIndex = 0; edgeIndex < edgePairs.length; edgeIndex++) {
 19	            edges.add(Edge.fromPair(edgePairs[edgeIndex], edgeIndex));
 20	        }
 21	
 22	        return fromEdges(vertexCount, edges);
 23	    }
 24	
 25	    public static Graph fromEdges(int vertexCount, Iterable<Edge> edges) {
 26	        validateVertexCount(vertexCount);
 27	        requireEdges(edges);
 28	
 29	        Builder builder = new Builder(vertexCount);
 30	        int edgeIndex = 0;
 31	        for (Edge edge : edges) {
 32	            builder.addEdge(edge, edgeIndex);
 33	            edgeIndex++;
 34	        }
 35	
 36	        return builder.build();
 37	    }
 38	
 39	    public int vertexCount() {
 40	        return adjacencyList.size();
 41	    }
 42	
 43	    @Override
 44	    public Iterator<Integer> iterator() {
 45	        return new VertexIterator(adjacencyList.size());
 46	    }
 47	
 48	    public List<Integer> neighborsOf(int vertex) {
 49	        validateVertexIndex(vertex);
 50	        return adjacencyList.get(vertex);
 51	    }
 52	
 53	    private static List<List<Integer>> toUnmodifiableAdjacencyList(
 54	            List<List<Integer>> adjacencyList) {
 55	        List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
 56	        for (List<Integer> neighbors : adjacencyList) {
 57	            immutableAdjacencyList.add(Collections.unmodifiableList(neighbors));
 58	        }
 59	
 60	        return Collections.unmodifiableList(immutableAdjacencyList);
 61	    }
 62	
 63	    private static void validateVertexCount(int vertexCount) {
 64	        if (vertexCount < 0) {
 65	            throw new IllegalArgumentException("Vertex count cannot be negative.");
 66	        }
 67	    }
 68	
 69	    private static void requireEdgePairs(int[][] edgePairs) {
 70	        if (edgePairs == null) {
 71	            throw new IllegalArgumentException("Edges cannot be null.");
 72	        }
 73	    }
 74	
 75	    private static void requireEdges(Iterable<Edge> edges) {
 76	        if (edges == null) {
 77	            throw new IllegalArgumentException("Edges cannot be null.");
 78	        }
 79	    }
 80	
 81	    private static Edge validateEdge(Edge edge, int edgeIndex) {
 82	        if (edge == null) {
 83	            throw new IllegalArgumentException(
 84	                    "Edge cannot be null. Invalid edge at index "
 85	                            + edgeIndex
 86	                            + ".");
 87	        }
 88	
 89	        return edge;
 90	    }
 91	
 92	    private static int validateVertex(int vertex, int vertexCount, int edgeIndex) {
 93	        if (vertex < 0 || vertex >= vertexCount) {
 94	            throw new IllegalArgumentException(
 95	                    "Edge at index "
 96	                            + edgeIndex
 97	                            + " references invalid vertex "
 98	                            + vertex
 99	                            + " for graph size "
100	                            + vertexCount
101	                            + ".");
102	        }
103	
104	        return vertex;
105	    }
106	
107	    private void validateVertexIndex(int vertex) {
108	        if (vertex < 0 || vertex >= adjacencyList.size()) {
109	            throw new IndexOutOfBoundsException(
110	                    "Vertex "
111	                            + vertex
112	                            + " is out of bounds for graph size "
113	                            + adjacencyList.size()
114	                            + ".");
115	        }
116	    }
117	
118	    private static final class Builder {
119	        private final List<List<Integer>> adjacencyList;
120	        private final int vertexCount;
121	
122	        private Builder(int vertexCount) {
123	            this.vertexCount = vertexCount;
124	            this.adjacencyList = initializeAdjacencyList(vertexCount);
125	        }
126	
127	        private void addEdge(Edge edge, int edgeIndex) {
128	            Edge validatedEdge = validateEdge(edge, edgeIndex);
129	            int source = validateVertex(validatedEdge.source(), vertexCount, edgeIndex);
130	            int destination = validateVertex(validatedEdge.destination(), vertexCount, edgeIndex);
131	            adjacencyList.get(source).add(destination);
132	            adjacencyList.get(destination).add(source);
133	        }
134	
135	        private Graph build() {
136	            return new Graph(toUnmodifiableAdjacencyList(adjacencyList));
137	        }
138	
139	        private static List<List<Integer>> initializeAdjacencyList(int vertexCount) {
140	            List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
141	            for (int vertex = 0; vertex < vertexCount; vertex++) {
142	                adjacencyList.add(new ArrayList<>());
143	            }
144	
145	            return adjacencyList;
146	        }
147	    }
148	
149	    private static final class VertexIterator implements Iterator<Integer> {
150	        private final int vertexCount;
151	        private int currentVertex;
152	
153	        private VertexIterator(int vertexCount) {
154	            this.vertexCount = vertexCount;
155	        }
156	
157	        @Override
158	        public boolean hasNext() {
159	            return currentVertex < vertexCount;
160	        }
161	
162	        @Override
163	        public Integer next() {
164	            if (!hasNext()) {
165	                throw new NoSuchElementException("No more vertices remain in this graph.");
166	            }
167	
168	            return currentVertex++;
169	        }
170	    }
171	}

